-- WASSAFRICA Commerce P0 foundation 2026-09-26
create extension if not exists pgcrypto;
alter table public.products add column if not exists reserved_stock integer not null default 0;
alter table public.products drop constraint if exists products_reserved_stock_check;
alter table public.products add constraint products_reserved_stock_check check (reserved_stock >= 0);
create table if not exists public.checkout_groups(id uuid primary key default gen_random_uuid(),buyer_user_id uuid references auth.users(id) on delete set null,status text not null default 'pending' check(status in('pending','paid','processing','completed','cancelled','problem')),currency text not null default 'XOF',subtotal numeric(12,2) not null default 0 check(subtotal>=0),delivery_fee numeric(12,2) not null default 0 check(delivery_fee>=0),total numeric(12,2) not null default 0 check(total>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.orders add column if not exists checkout_group_id uuid references public.checkout_groups(id) on delete set null;
create index if not exists orders_checkout_group_idx on public.orders(checkout_group_id);
create table if not exists public.carts(id uuid primary key default gen_random_uuid(),buyer_user_id uuid not null references auth.users(id) on delete cascade,currency text not null default 'XOF',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(buyer_user_id));
create table if not exists public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts(id) on delete cascade,product_id uuid not null references public.products(id) on delete restrict,quantity integer not null default 1 check(quantity between 1 and 99),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(cart_id,product_id));
create table if not exists public.commerce_favorites(user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,status text not null,actor_user_id uuid references auth.users(id) on delete set null,note text,created_at timestamptz not null default now());
create index if not exists order_status_history_order_idx on public.order_status_history(order_id,created_at desc);
create table if not exists public.deliveries(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete cascade,method text not null check(method in('pickup','delivery','digital','external_carrier')),status text not null default 'pending' check(status in('pending','confirmed','preparing','ready','shipped','in_transit','delivered','received','cancelled','problem')),city text,address text,fee numeric(12,2) not null default 0 check(fee>=0),carrier text,tracking_number text,estimated_at timestamptz,shipped_at timestamptz,delivered_at timestamptz,received_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.commerce_reviews(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,order_item_id uuid references public.order_items(id) on delete set null,product_id uuid references public.products(id) on delete set null,business_id uuid not null references public.businesses(id) on delete cascade,reviewer_user_id uuid not null references auth.users(id) on delete cascade,review_type text not null check(review_type in('product','seller')),rating integer not null check(rating between 1 and 5),title text,body text,is_published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(order_id,reviewer_user_id,review_type,product_id));
create index if not exists commerce_reviews_product_idx on public.commerce_reviews(product_id,is_published,created_at desc);
create index if not exists commerce_reviews_business_idx on public.commerce_reviews(business_id,is_published,created_at desc);
create or replace function private.reserve_order_item_stock() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.products set reserved_stock=reserved_stock+new.quantity where id=new.product_id and product_type='physical'; return new; end; $$;
revoke all on function private.reserve_order_item_stock() from public,anon,authenticated;
drop trigger if exists trg_reserve_order_item_stock on public.order_items;
create trigger trg_reserve_order_item_stock after insert on public.order_items for each row execute function private.reserve_order_item_stock();
create or replace function private.sync_order_inventory() returns trigger language plpgsql security definer set search_path='' as $$ declare v_item record; begin
if new.payment_status='paid' and old.payment_status is distinct from 'paid' then for v_item in select oi.product_id,oi.quantity from public.order_items oi join public.products p on p.id=oi.product_id where oi.order_id=new.id and p.product_type='physical' loop update public.products set reserved_stock=greatest(0,reserved_stock-v_item.quantity) where id=v_item.product_id; end loop; end if;
if new.status in('delivered','cancelled') and old.status is distinct from new.status then for v_item in select oi.product_id,oi.quantity from public.order_items oi join public.products p on p.id=oi.product_id where oi.order_id=new.id and p.product_type='physical' loop if new.status='cancelled' and new.payment_status<>'paid' then update public.products set stock=stock+v_item.quantity,reserved_stock=greatest(0,reserved_stock-v_item.quantity) where id=v_item.product_id; elsif new.status='delivered' and new.payment_status<>'paid' then update public.products set reserved_stock=greatest(0,reserved_stock-v_item.quantity) where id=v_item.product_id; end if; end loop; end if;
if new.payment_status in('failed','cancelled') and old.payment_status is distinct from new.payment_status and old.payment_status<>'paid' then for v_item in select oi.product_id,oi.quantity from public.order_items oi join public.products p on p.id=oi.product_id where oi.order_id=new.id and p.product_type='physical' loop update public.products set stock=stock+v_item.quantity,reserved_stock=greatest(0,reserved_stock-v_item.quantity) where id=v_item.product_id; end loop; end if; return new; end; $$;
revoke all on function private.sync_order_inventory() from public,anon,authenticated;
drop trigger if exists trg_sync_order_inventory on public.orders;
create trigger trg_sync_order_inventory after update of status,payment_status on public.orders for each row execute function private.sync_order_inventory();
create or replace function private.record_order_status() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then insert into public.order_status_history(order_id,status,actor_user_id) values(new.id,new.status,(select auth.uid())); elsif old.status is distinct from new.status then insert into public.order_status_history(order_id,status,actor_user_id) values(new.id,new.status,(select auth.uid())); end if; return new; end; $$;
revoke all on function private.record_order_status() from public,anon,authenticated;
drop trigger if exists trg_record_order_status on public.orders;
create trigger trg_record_order_status after insert or update of status on public.orders for each row execute function private.record_order_status();
create or replace function private.ensure_order_delivery() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.deliveries(order_id,method,status,city,address,fee) values(new.id,new.delivery_method,case when new.status='delivered' then 'delivered' else 'pending' end,new.delivery_city,new.delivery_address,new.delivery_fee) on conflict(order_id) do update set method=excluded.method,city=excluded.city,address=excluded.address,fee=excluded.fee,updated_at=now(); return new; end; $$;
revoke all on function private.ensure_order_delivery() from public,anon,authenticated;
drop trigger if exists trg_ensure_order_delivery on public.orders;
create trigger trg_ensure_order_delivery after insert on public.orders for each row execute function private.ensure_order_delivery();
alter table public.carts enable row level security; alter table public.cart_items enable row level security; alter table public.commerce_favorites enable row level security; alter table public.order_status_history enable row level security; alter table public.deliveries enable row level security; alter table public.commerce_reviews enable row level security; alter table public.checkout_groups enable row level security;
drop policy if exists carts_owner_all on public.carts; create policy carts_owner_all on public.carts for all to authenticated using((select auth.uid())=buyer_user_id) with check((select auth.uid())=buyer_user_id);
drop policy if exists cart_items_owner_all on public.cart_items; create policy cart_items_owner_all on public.cart_items for all to authenticated using(exists(select 1 from public.carts c where c.id=cart_items.cart_id and c.buyer_user_id=(select auth.uid()))) with check(exists(select 1 from public.carts c where c.id=cart_items.cart_id and c.buyer_user_id=(select auth.uid())));
drop policy if exists favorites_owner_all on public.commerce_favorites; create policy favorites_owner_all on public.commerce_favorites for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists order_history_participant_read on public.order_status_history; create policy order_history_participant_read on public.order_status_history for select to authenticated using(exists(select 1 from public.orders o left join public.businesses b on b.id=o.business_id where o.id=order_status_history.order_id and(o.buyer_user_id=(select auth.uid()) or b.owner_id=(select auth.uid()))));
drop policy if exists deliveries_participant_read on public.deliveries; create policy deliveries_participant_read on public.deliveries for select to authenticated using(exists(select 1 from public.orders o left join public.businesses b on b.id=o.business_id where o.id=deliveries.order_id and(o.buyer_user_id=(select auth.uid()) or b.owner_id=(select auth.uid()))));
drop policy if exists reviews_public_read on public.commerce_reviews; create policy reviews_public_read on public.commerce_reviews for select to anon,authenticated using(is_published=true);
drop policy if exists reviews_owner_insert on public.commerce_reviews; create policy reviews_owner_insert on public.commerce_reviews for insert to authenticated with check(reviewer_user_id=(select auth.uid()) and exists(select 1 from public.orders o where o.id=commerce_reviews.order_id and o.buyer_user_id=(select auth.uid()) and o.status='delivered'));
drop policy if exists reviews_owner_update on public.commerce_reviews; create policy reviews_owner_update on public.commerce_reviews for update to authenticated using(reviewer_user_id=(select auth.uid())) with check(reviewer_user_id=(select auth.uid()));
drop policy if exists reviews_owner_delete on public.commerce_reviews; create policy reviews_owner_delete on public.commerce_reviews for delete to authenticated using(reviewer_user_id=(select auth.uid()));
drop policy if exists checkout_groups_owner_read on public.checkout_groups; create policy checkout_groups_owner_read on public.checkout_groups for select to authenticated using((select auth.uid())=buyer_user_id);
revoke all on table public.carts,public.cart_items,public.commerce_favorites,public.order_status_history,public.deliveries,public.commerce_reviews,public.checkout_groups from anon,authenticated;
grant select,insert,update,delete on public.carts,public.cart_items,public.commerce_favorites to authenticated;
grant select on public.order_status_history,public.deliveries,public.commerce_reviews,public.checkout_groups to anon,authenticated;
grant insert,update,delete on public.commerce_reviews to authenticated;
